    float r = v[1], g = v[2], b = v[3], mayor = fmaxf(r, fmaxf(g,b)), menor = fminf(r, fminf(g,b)), delta = mayor - menor;
    float tono = delta == 0 ? 0 : mayor == r ? 60 * fmodf((g-b)/delta + 6, 6) : mayor == g ? 60 * ((b-r)/delta + 2) : 60 * ((r-g)/delta + 4);
    hsv[0] = roundf(tono*10)/10; hsv[1] = mayor == 0 ? 0 : roundf(delta*1000/mayor)/10; hsv[2] = roundf(fminf(100, v[0]*100.0f/44032)*10)/10;
}
inline float color_componente(const String& parte, const char* bloque) { float hsv[3] = {}; color_hsv(hsv, bloque); return hsv[parte[0]-'0']; }
inline String color_nombre(const char* bloque) {
    float h[3] = {}; color_hsv(h, bloque);
    if (h[2] < 3) return String("negro"); if (h[1] < 20) return String(h[2] > 20 ? "blanco" : "gris");
    return String(h[0] < 20 ? "rojo" : h[0] < 45 ? "naranja" : h[0] < 70 ? "amarillo" : h[0] < 170 ? "verde" : h[0] < 260 ? "azul" : h[0] < 330 ? "morado" : "rojo");
}
